input.sparql:
SELECT ?ahu ?point ?ts WHERE {
  ?ahu brick:hasTag "AHU02" .
  ?point brick:isOutputOf ?ahu .
  ?point brick:isAType brick:ElectricalPower .
  ?point ref:hasTimeseriesId ?ts .
}

SELECT ?s ?ifc ?label WHERE {
  ?s a brick:AirHandlingUnit .
  ?s ref:ifcName ?ifc .
  OPTIONAL { ?s rdfs:label ?label }
} LIMIT 30

SELECT ?ahu ?ifc ?label WHERE {
  ?ahu a brick:AHU .
  OPTIONAL { ?ahu ref:ifcName ?ifc }
  OPTIONAL { ?ahu rdfs:label ?label }
} LIMIT 30

SELECT ?point ?ptype ?ts WHERE {
  ?point brick:isPointOf <http://buildgraph.org/BG_medium_office_2004_0000#AHU02> .
  OPTIONAL { ?point a ?ptype }
  OPTIONAL { ?point ref:hasTimeseriesId ?ts }
} LIMIT 50

SELECT ?point ?rel ?other ?ts WHERE {
  ?point a brick:Electric_Power_Sensor .
  ?point ?rel ?other .
  OPTIONAL { ?point ref:hasTimeseriesId ?ts }
  FILTER(?rel = brick:isPointOf || ?rel = ref:hasTimeseriesId)
} LIMIT 50

SELECT DISTINCT ?point ?ts WHERE {
  ?point ref:hasTimeseriesId ?ts .
  ?point a brick:Electric_Power_Sensor .
} LIMIT 50

SELECT ?point ?ts WHERE {
  ?point a brick:Electric_Power_Sensor .
  ?point ref:hasTimeseriesId ?ts .
} LIMIT 30
